CREATE OR REPLACE FUNCTION public.anonymize_candidate(p_candidate_id uuid, p_reason text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$
DECLARE v_cand public.candidates%rowtype;
BEGIN
  SELECT * INTO v_cand FROM public.candidates WHERE id = p_candidate_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'anonymize_candidate: % not found', p_candidate_id; END IF;
  -- tenant + role guard (defense in depth; RLS-independent because SECURITY DEFINER)
  IF v_cand.organization_id <> public.get_user_org_id() OR NOT public.is_internal_user() THEN
    RAISE EXCEPTION 'anonymize_candidate: not permitted';
  END IF;
  IF v_cand.anonymized_at IS NOT NULL THEN
    RETURN jsonb_build_object('candidate', p_candidate_id, 'already_anonymized', true); END IF;
  -- delete PII-bearing children that are NOT statutory financial records
  DELETE FROM public.documents WHERE candidate_id = p_candidate_id; -- storage objects removed by edge fn beforehand
  DELETE FROM public.notes WHERE related_entity_type='candidate' AND related_entity_id=p_candidate_id;
  DELETE FROM public.onboarding_responses WHERE candidate_id = p_candidate_id;
  DELETE FROM public.candidate_profile_tokens WHERE candidate_id = p_candidate_id;
  -- scrub free-text bodies on communications (keep row for audit, drop content)
  UPDATE public.communications SET subject=NULL, body=NULL, content=NULL WHERE candidate_id = p_candidate_id; -- only existing cols
  -- scrub the candidate row itself
  UPDATE public.candidates SET
    first_name='[gewist]', last_name='[gewist]', middle_name=NULL, initials=NULL,
    email=NULL, phone=NULL, phone_nl=NULL, bsn=NULL, iban=NULL, bank_account_holder=NULL,
    date_of_birth=NULL, birth_place=NULL, birth_country=NULL, nationality=NULL, gender=NULL,
    marital_status=NULL, address_street=NULL, address_postal=NULL, address_city=NULL,
    address_country=NULL, address_lat=NULL, address_lng=NULL,
    emergency_contact_name=NULL, emergency_contact_phone=NULL,
    id_document_number=NULL, id_document_type=NULL, id_document_valid_until=NULL,
    notes=NULL, availability_notes=NULL, external_id=NULL,
    cv_file_url=NULL, cv_raw_text=NULL, cv_has_photo=NULL, cv_pseudonymization_meta=NULL, cv_pseudonymized_at=NULL,
    ai_analysis=NULL, ai_summary=NULL, ai_red_flags=NULL, ai_positive_signals=NULL, ai_risk_factors=NULL,
    ai_interview_questions=NULL, ai_target_functions=NULL, ai_languages=NULL, ai_classification=NULL,
    ai_function_group=NULL, ai_reliability_score=NULL, ai_status=NULL, ai_stability=NULL,
    status='uitgeschreven', portal_enabled=false, auth_user_id=NULL, anonymized_at=now()
  WHERE id = p_candidate_id;
  INSERT INTO public.audit_log(organization_id,user_id,action,table_name,record_id,old_values,new_values,reason)
  VALUES (v_cand.organization_id, auth.uid(), 'delete', 'candidates', p_candidate_id,
          to_jsonb(v_cand)-'bsn'-'iban', jsonb_build_object('anonymized',true),
          coalesce(p_reason,'AVG art.17 erasure'));
  RETURN jsonb_build_object('candidate', p_candidate_id, 'anonymized', true);
END; $$;
REVOKE EXECUTE ON FUNCTION public.anonymize_candidate(uuid,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.anonymize_candidate(uuid,text) TO authenticated, service_role;
